// MicroBoy Jukebox: 20 animated pixel scenes, each with its own song for the
// GBA's four PSG channels. A / R next scene, B / L previous, Start music
// on/off, Select auto-play (moves on whenever a song ends).
// Art and music are generated by gen.py (see scenes.py and music.py).
// Written for this project; public domain / CC0.
#include <stdint.h>

#include "jukebox.h"

#define REG16(a) (*(volatile uint16_t*) (a))
#define DISPCNT REG16(0x4000000)
#define VCOUNT REG16(0x4000006)
#define BGCNT(n) REG16(0x4000008 + 2 * (n))
#define BGHOFS(n) REG16(0x4000010 + 4 * (n))
#define BGVOFS(n) REG16(0x4000012 + 4 * (n))
#define BLDCNT REG16(0x4000050)
#define BLDY REG16(0x4000054)
#define SOUND1CNT_L REG16(0x4000060)
#define SOUND1CNT_H REG16(0x4000062)
#define SOUND1CNT_X REG16(0x4000064)
#define SOUND2CNT_L REG16(0x4000068)
#define SOUND2CNT_H REG16(0x400006C)
#define SOUND3CNT_L REG16(0x4000070)
#define SOUND3CNT_H REG16(0x4000072)
#define SOUND3CNT_X REG16(0x4000074)
#define SOUND4CNT_L REG16(0x4000078)
#define SOUND4CNT_H REG16(0x400007C)
#define SOUNDCNT_L REG16(0x4000080)
#define SOUNDCNT_H REG16(0x4000082)
#define SOUNDCNT_X REG16(0x4000084)
#define WAVE_RAM ((volatile uint16_t*) 0x4000090)
#define KEYINPUT REG16(0x4000130)
#define WAITCNT REG16(0x4000204)

#define BG_PAL ((volatile uint16_t*) 0x5000000)
#define OBJ_PAL ((volatile uint16_t*) 0x5000200)
#define VRAM32 ((volatile uint32_t*) 0x6000000)
#define SCREENBLOCK(n) ((volatile uint16_t*) (0x6000000 + (n) * 0x800))
#define OBJ_VRAM32 ((volatile uint32_t*) 0x6010000)
#define OAM ((volatile uint16_t*) 0x7000000)

#define KEY_A 0x001
#define KEY_B 0x002
#define KEY_SELECT 0x004
#define KEY_START 0x008
#define KEY_R 0x100
#define KEY_L 0x200

#define ENV(vol, step) ((uint16_t) (((vol) << 12) | ((step) << 8)))

// OBJ tile layout: name strip 0-11, particles 16+, mascot 32+.
#define NAME_TILE 0
#define NAME_TILES 12
#define PART_TILE 16
#define MASCOT_TILE 32
#define MAX_PARTICLES 28
#define OAM_NAME 0
#define OAM_MASCOT 3
#define OAM_PART 12  // mascot members use 3..10

static const int8_t sine64[64] = {
    0, 6, 12, 19, 24, 30, 36, 41, 45, 49, 53, 56, 59, 61, 63, 64, 64, 64, 63, 61, 59, 56, 53, 49, 45, 41,
    36, 30, 24, 19, 12, 6, 0, -6, -12, -19, -24, -30, -36, -41, -45, -49, -53, -56, -59, -61, -63, -64,
    -64, -64, -63, -61, -59, -56, -53, -49, -45, -41, -36, -30, -24, -19, -12, -6,
};

static const Scene* sc;
static int current;
static uint32_t rng;  // .bss only (the linker script has no .data); seeded in main()
static uint32_t scrollAcc[4];
static uint16_t shadow[64];  // BG palette as currently shown
static uint8_t fxTimer[3];
static uint8_t twinkleOn[3];
static int flashTimer, flashPhase;

typedef struct { int32_t x, y; uint8_t phase; } Particle;
static Particle parts[MAX_PARTICLES];
static uint8_t partFrame, partTimer;
static int32_t mascotX, mascotY;
static uint8_t mascotFrame, mascotTimer, mascotPhase;

static uint32_t stripBuf[NAME_TILES * 8];
static int nameTimer;

static int music, autoplay;
static int step, stepTimer;

static uint32_t rand32(void) {
    rng = rng * 1664525u + 1013904223u;
    return rng >> 8;
}

// rand32() scaled to [0, n) without a divide (the ARM7 has none).
static int randBelow(int n) {
    return (int) (((rand32() & 0xFFFF) * (uint32_t) n) >> 16);
}

static void vsync(void) {
    while (VCOUNT >= 160) {}
    while (VCOUNT < 160) {}
}

// --- text ------------------------------------------------------------------------------------

static void stripPixel(int x, int y, int color) {
    if (x < 0 || x >= NAME_TILES * 8 || y < 0 || y >= 8) return;
    uint32_t* row = &stripBuf[(x >> 3) * 8 + y];
    int shift = (x & 7) * 4;
    *row = (*row & ~(0xFu << shift)) | ((uint32_t) color << shift);
}

static void showText(const char* s) {
    for (int i = 0; i < NAME_TILES * 8; ++i) stripBuf[i] = 0;
    for (int x = 0; *s; ++s, x += 4) {
        int g = 0;
        for (int i = 0; fontChars[i]; ++i) {
            if (fontChars[i] == *s) { g = i; break; }
        }
        for (int i = 0; i < 15; ++i) {
            if (fontGlyphs[g] & (1 << i)) {
                stripPixel(x + i % 3 + 1, i / 3 + 2, 2);
                stripPixel(x + i % 3, i / 3 + 1, 1);
            }
        }
    }
    for (int i = 0; i < NAME_TILES * 8; ++i) OBJ_VRAM32[NAME_TILE * 8 + i] = stripBuf[i];
    nameTimer = 180;
}

static void setSprite(int n, int x, int y, int shape, int size, int tile, int pal) {
    volatile uint16_t* o = &OAM[n * 4];
    o[0] = (uint16_t) ((y & 0xFF) | (shape << 14));
    o[1] = (uint16_t) ((x & 0x1FF) | (size << 14));
    o[2] = (uint16_t) (tile | (pal << 12));
}

static void hideSprite(int n) {
    OAM[n * 4] = 0x0200;
}

// --- music -------------------------------------------------------------------------------------

static void loadWave(const uint8_t* w) {
    SOUND3CNT_L = 0x40;  // play bank 1 so writes land in bank 0
    for (int i = 0; i < 8; ++i) WAVE_RAM[i] = (uint16_t) (w[2 * i] | (w[2 * i + 1] << 8));
    SOUND3CNT_L = 0x80;
}

static void silence(void) {
    SOUND1CNT_H = 0; SOUND1CNT_X = 0x8000;
    SOUND2CNT_L = 0; SOUND2CNT_H = 0x8000;
    SOUND3CNT_H = 0;
    SOUND4CNT_L = 0; SOUND4CNT_H = 0x8000;
}

static void soundOn(int on) {
    if (on) {
        SOUNDCNT_X = 0x80;
        SOUNDCNT_L = 0xFF77;
        SOUNDCNT_H = 0x0002;
        SOUND1CNT_L = 0;
        loadWave(sc->wave);
    } else {
        SOUNDCNT_X = 0;
    }
}

static void playStep(int s) {
    uint16_t v = sc->lead[s];
    if (v == 0xFFFF) {
        SOUND1CNT_H = (uint16_t) (sc->leadDuty << 6);
        SOUND1CNT_X = 0x8000;
    } else if (v) {
        SOUND1CNT_H = (uint16_t) ((sc->leadDuty << 6) | ENV(sc->leadVol, sc->leadStep));
        SOUND1CNT_X = 0x8000 | v;
    }
    v = sc->harm[s];
    if (v == 0xFFFF) {
        SOUND2CNT_L = (uint16_t) (sc->harmDuty << 6);
        SOUND2CNT_H = 0x8000;
    } else if (v) {
        SOUND2CNT_L = (uint16_t) ((sc->harmDuty << 6) | ENV(sc->harmVol, sc->harmStep));
        SOUND2CNT_H = 0x8000 | v;
    }
    v = sc->bass[s];
    if (v == 0xFFFF) {
        SOUND3CNT_H = 0;
    } else if (v) {
        SOUND3CNT_H = (uint16_t) (sc->bassVol << 13);
        SOUND3CNT_X = 0x8000 | v;
    }
    switch (sc->drums[s]) {
    case 1: SOUND4CNT_L = ENV(4, 1); SOUND4CNT_H = 0x8000 | (1 << 4); break;           // hi-hat
    case 2: SOUND4CNT_L = ENV(7, 2); SOUND4CNT_H = 0x8000 | (4 << 4) | 2; break;       // snare
    case 3: SOUND4CNT_L = ENV(11, 1); SOUND4CNT_H = 0x8000 | (7 << 4) | 6; break;      // kick
    case 4: SOUND4CNT_L = ENV(4, 3); SOUND4CNT_H = 0x8000 | (1 << 4); break;           // open hat
    }
}

// --- scenes ------------------------------------------------------------------------------------

static void fade(int from, int to) {
    BLDCNT = 0x00FF;  // brightness decrease on every layer and the backdrop
    int d = to > from ? 2 : -2;
    for (int v = from; v != to; v += d) {
        vsync();
        BLDY = (uint16_t) v;
    }
    vsync();
    BLDY = (uint16_t) to;
}

static void loadScene(int n) {
    fade(0, 16);
    silence();
    DISPCNT = 0x0080;  // forced blank: VRAM is free to write
    current = n;
    sc = &scenes[n];

    for (int i = 0; i < sc->tileWords; ++i) VRAM32[i] = sc->tiles[i];
    uint16_t layers = 0;
    for (int l = 0; l < 4; ++l) {
        scrollAcc[l] = 0;
        BGHOFS(l) = 0;
        BGVOFS(l) = 0;
        if (!sc->map[l]) continue;
        volatile uint16_t* sb = SCREENBLOCK(24 + 2 * l);
        int entries = sc->blocks[l] * 1024;
        for (int i = 0; i < entries; ++i) sb[i] = sc->map[l][i];
        BGCNT(l) = (uint16_t) (l | ((24 + 2 * l) << 8) | ((sc->blocks[l] == 2 ? 1 : 0) << 14));
        layers |= (uint16_t) (0x100 << l);
    }
    for (int i = 0; i < 64; ++i) BG_PAL[i] = shadow[i] = sc->pal[i];
    for (int i = 0; i < 16; ++i) {
        OBJ_PAL[16 + i] = sc->pal[64 + i];
        OBJ_PAL[32 + i] = sc->pal[80 + i];
    }
    for (int k = 0; k < 3; ++k) fxTimer[k] = twinkleOn[k] = 0;
    flashTimer = 120 + (int) (rand32() & 255);
    flashPhase = 0;

    // Sprites
    for (int i = 0; i < 128; ++i) hideSprite(i);
    int pwords = sc->pframes * 8;
    for (int i = 0; i < pwords; ++i) OBJ_VRAM32[PART_TILE * 8 + i] = sc->ptiles[i];
    for (int i = 0; i < sc->pcount && i < MAX_PARTICLES; ++i) {
        parts[i].x = (int32_t) randBelow(240) << 8;
        parts[i].y = (int32_t) randBelow(160) << 8;
        parts[i].phase = (uint8_t) rand32();
    }
    partFrame = partTimer = 0;
    int tilesPer = sc->msize == 32 ? 16 : 4;
    int mwords = sc->mframes * tilesPer * 8;
    for (int i = 0; i < mwords; ++i) OBJ_VRAM32[MASCOT_TILE * 8 + i] = sc->mtiles[i];
    mascotX = sc->mx << 8;
    mascotY = sc->my << 8;
    mascotFrame = mascotTimer = mascotPhase = 0;

    showText(sc->name);
    step = 0;
    stepTimer = 0;
    if (music) soundOn(1);

    DISPCNT = (uint16_t) (layers | 0x1000 | 0x0040);  // mode 0, OBJ on, 1D mapping
    fade(16, 0);
    BLDCNT = 0;
}

// --- per-frame effects ----------------------------------------------------------------------------

static void runEffects(void) {
    for (int k = 0; k < 3; ++k) {
        const uint8_t* f = sc->fx[k];
        if (!f[0]) continue;
        int base = f[1] * 16 + f[2];
        if (f[0] == 1) {  // cycle
            if (++fxTimer[k] < f[4]) continue;
            fxTimer[k] = 0;
            uint16_t last = shadow[base + f[3] - 1];
            for (int i = f[3] - 1; i > 0; --i) shadow[base + i] = shadow[base + i - 1];
            shadow[base] = last;
            for (int i = 0; i < f[3]; ++i) BG_PAL[base + i] = shadow[base + i];
        } else if (f[0] == 2) {  // twinkle: off for a moment every f[4] frames
            if (++fxTimer[k] >= f[4]) fxTimer[k] = 0;
            int on = fxTimer[k] >= 5;
            if (on != twinkleOn[k]) {
                twinkleOn[k] = (uint8_t) on;
                shadow[base] = on ? sc->pal[base] : sc->pal[base + 1];
                BG_PAL[base] = shadow[base];
            }
        } else if (f[0] == 3 && sc->flash) {  // lightning
            if (flashPhase == 0 && --flashTimer <= 0) flashPhase = 1;
            if (flashPhase) {
                // flash 4 frames, dark 3, flash 3, then restore
                int lit = flashPhase <= 4 || (flashPhase > 7 && flashPhase <= 10);
                for (int i = 0; i < 16; ++i) BG_PAL[f[1] * 16 + i] = lit ? sc->flash[i] : shadow[f[1] * 16 + i];
                if (++flashPhase > 10) {
                    flashPhase = 0;
                    flashTimer = 150 + (int) (rand32() & 511);
                }
            }
        }
    }
}

static void updateSprites(uint32_t t) {
    // Particles
    if (sc->pcount) {
        if (sc->panim && ++partTimer >= sc->panim) {
            partTimer = 0;
            partFrame ^= 1;
        }
        for (int i = 0; i < sc->pcount && i < MAX_PARTICLES; ++i) {
            Particle* p = &parts[i];
            int s = sine64[(p->phase + (t >> 1)) & 63];
            p->x += sc->pvx + s * sc->psway;
            p->y += sc->pvy;
            if (p->y > (168 << 8)) { p->y -= 176 << 8; p->x = (int32_t) randBelow(240) << 8; }
            if (p->y < -(8 << 8)) { p->y += 176 << 8; p->x = (int32_t) randBelow(240) << 8; }
            if (p->x > (248 << 8)) p->x -= 256 << 8;
            if (p->x < -(8 << 8)) p->x += 256 << 8;
            int frame = sc->pframes > 1 ? ((partFrame + i) & 1) : 0;
            setSprite(OAM_PART + i, p->x >> 8, p->y >> 8, 0, 0, PART_TILE + frame, 1);
        }
    }
    // Mascot (or a line of them)
    if (sc->mframes) {
        int size = sc->msize;
        int tilesPer = size == 32 ? 16 : 4;
        int s = sine64[(t * 2) & 63];
        int x = mascotX >> 8, y = mascotY >> 8;
        int perKind = sc->mkinds ? 2 : sc->mframes;  // frames per member kind
        int frame = mascotFrame;
        if (++mascotTimer >= sc->manim) {
            mascotTimer = 0;
            if (++mascotFrame >= perKind) mascotFrame = 0;
        }
        switch (sc->mmotion) {
        case 1: y += (s * sc->mamp) >> 6; break;  // bob
        case 2: {                                  // hop
            int a = sine64[(t * 3) & 63];
            if (a < 0) a = -a;
            y -= (a * sc->mamp) >> 6;
            frame = a > 8 ? 1 : 0;
            break;
        }
        case 3: case 4: case 5:                    // drift, swim, waddle
            mascotX += sc->mvx;
            if (sc->mcount <= 1 && mascotX > (240 << 8)) mascotX = -(size << 8);
            if (sc->mcount > 1 && mascotX > (560 << 8)) mascotX -= 320 << 8;
            y += (s * sc->mamp) >> 6;
            break;
        }
        for (int k = 0; k < sc->mcount && k < 8; ++k) {
            // Members trail the leader; the line wraps around a 320 px loop.
            int mx = x - sc->moffs[k];
            // (ifs, not while loops: LLVM turns those into a divide, which the ARM7 lacks)
            if (mx >= 288) mx -= 320;
            if (mx >= 288) mx -= 320;
            if (mx < -32) mx += 320;
            if (mx < -32) mx += 320;
            int kind = (sc->mkinds >> k) & 1;
            int f = sc->mkinds ? kind * 2 + ((frame + k) & 1) : frame;
            if (sc->mcount > 1 && sc->mmotion == 5 && !kind) {
                // waddling penguins rock up and down out of step with each other
                y = (mascotY >> 8) + (((k + (int) (t >> 3)) & 1) ? 0 : -1);
            } else if (sc->mcount > 1) {
                y = mascotY >> 8;
            }
            setSprite(OAM_MASCOT + k, mx, y, 0, size == 32 ? 2 : 1, MASCOT_TILE + f * tilesPer, 2);
        }
    }
    // Name
    if (nameTimer > 0) {
        --nameTimer;
        for (int i = 0; i < 3; ++i) setSprite(OAM_NAME + i, 6 + i * 32, 148, 1, 1, NAME_TILE + i * 4, 0);
    } else {
        for (int i = 0; i < 3; ++i) hideSprite(OAM_NAME + i);
    }
}

int main(void) {
    WAITCNT = 0x4317;
    rng = 0x1234567;
    music = 1;
    // Text colours (OBJ bank 0): white, shadow, accent.
    OBJ_PAL[1] = 0x7FFF;
    OBJ_PAL[2] = 0x0842;
    OBJ_PAL[3] = 0x6F8F;
    soundOn(1);
    sc = &scenes[0];
    loadScene(0);

    uint32_t t = 0;
    uint16_t prev = 0;
    for (;;) {
        vsync();
        for (int l = 0; l < 4; ++l) BGHOFS(l) = (uint16_t) (scrollAcc[l] >> 8);
        runEffects();
        updateSprites(t);

        for (int l = 0; l < 4; ++l) {
            if (!sc->map[l]) continue;
            uint32_t mask = ((uint32_t) sc->blocks[l] << 16) - 1;  // blocks × 256 px, in 1/256 px
            scrollAcc[l] = (scrollAcc[l] + (uint32_t) (int32_t) sc->scroll[l]) & mask;
        }

        uint16_t keys = (uint16_t) (~KEYINPUT & 0x3FF);
        uint16_t pressed = keys & ~prev;
        prev = keys;
        int next = -1;
        if (pressed & (KEY_A | KEY_R)) next = current == SCENE_COUNT - 1 ? 0 : current + 1;
        if (pressed & (KEY_B | KEY_L)) next = current == 0 ? SCENE_COUNT - 1 : current - 1;
        if (pressed & KEY_START) {
            music = !music;
            soundOn(music);
            stepTimer = 0;
        }
        if (pressed & KEY_SELECT) {
            autoplay = !autoplay;
            showText(autoplay ? "AUTO PLAY ON" : "AUTO PLAY OFF");
        }

        if (music && stepTimer-- <= 0) {
            playStep(step);
            stepTimer = sc->tempo + ((step & 1) ? -sc->swing : sc->swing) - 1;
            if (++step == 256) {
                step = 0;
                if (autoplay) next = current == SCENE_COUNT - 1 ? 0 : current + 1;
            }
        }
        if (next >= 0) loadScene(next);
        ++t;
    }
}
